-- oracle/03b_data_fix.sql
-- Targeted reload of only the tables that failed in previous 03_data.sql runs.
-- Assumes users, floors, vehicle_types, cancellation_rules, parking_slots, audit_logs
-- are already loaded and correct. Safe to re-run: deletes first, then inserts.
SET DEFINE OFF;

-- 1. Clear only the affected tables (reverse FK order)
DELETE FROM QSPARK_REVENUE_COLLECTIONS;
DELETE FROM QSPARK_BOOKING_EVENTS;
DELETE FROM QSPARK_WALLET_TRANSACTIONS;
DELETE FROM QSPARK_BOOKINGS;
DELETE FROM QSPARK_SYSTEM_SETTINGS;
COMMIT;

-- 2. Re-insert (FK-safe order)
-- bookings: 56 rows

-- wallet_transactions: 137 rows

-- booking_events: 100 rows

-- revenue_collections: 61 rows

-- system_settings: 1 rows

COMMIT;
